package ch.bbw.zork;import java.util.List;import java.util.Random;/** * Class Game - the main class of the "Zork" game. * * Author: Michael Kolling, 1.1, March 2000 * Refactoring: Rinaldo Lanza, September 2020 */public class Game {	private Parser parser;	private Room currentRoom;	private Player player;	private Random random;	private static final int SEARCH_FAIL_CHANCE = 25;	private static final int CONTINUE_FAIL_CHANCE = 20;	public Game() {		parser = new Parser(System.in);		player = new Player();		random = new Random();		createRooms();	}	private void createRooms() {		Room room1 = new Room("Room behind Door 1", 10);		room1.addItem(new Item(ItemType.KEY, "Key"));		room1.lock();		Room room2 = new Room("Room behind Door 2");		Room room3 = new Room("Room behind Door 3", 15);		Room room4 = new Room("Room behind Door 4", 5);		Room room5 = new Room("Room behind Door 5");		room3.makeDark();		room3.addItem(new Item(ItemType.FLASHLIGHT, "Flashlight"));		room4.makeDark();		room1.setExit("forward", room2);		room2.setExit("backward", room1);		room2.setExit("forward", room3);		room3.setExit("backward", room2);		room3.setExit("forward", room4);		room4.setExit("backward", room3);		room4.setExit("forward", room5);		room5.setExit("backward", room4);		currentRoom = room1;	}	private boolean unlockCurrentDoor() {		if (!currentRoom.isLocked()) {			return true;		}		if (!player.hasItem(ItemType.KEY)) {			System.out.println("The door is locked. You need to find a key.");			return false;		}		player.removeItem(ItemType.KEY);		currentRoom.unlock();		System.out.println("You unlocked the door with your key.");		return true;	}	public void play() {		printWelcome();		boolean finished = false;		while (!finished) {			Command command = parser.getCommand();			finished = processCommand(command);		}		System.out.println("Thank you for playing. Good bye.");	}	private void printWelcome() {		System.out.println();		System.out.println("Welcome to Zork!");		System.out.println("Zork is a simple adventure game.");		System.out.println("Type 'help' if you need help.");		System.out.println();		System.out.println(currentRoom.longDescription());	}	/**	 * Dunkelheit kann Aktionen verhindern, wenn die Flashlight aus	 * oder ihre Batterie leer ist.	 */	private boolean failsInDarkness(int failChancePercent) {		if (!currentRoom.isDark()) {			return false;		}		if (player.isFlashlightOn()) {			return false;		}		return random.nextInt(100) < failChancePercent;	}	/**	 * Prueft Dunkelheit und Schloss vor dem Sieg oder Raumwechsel.	 *	 * @return true, wenn der Spieler entkommen ist	 */	private boolean continueToNextRoom() {		if (failsInDarkness(CONTINUE_FAIL_CHANCE)) {			System.out.println(					"You stumble around in the dark and can't find the door."			);			return false;		}		Room nextRoom = currentRoom.nextRoom("forward");		if (!unlockCurrentDoor()) {			return false;		}		if (nextRoom == null) {			System.out.println("You reached the final door and escaped!");			return true;		}		currentRoom = nextRoom;		System.out.println(currentRoom.longDescription());		return false;	}	private void returnToPreviousRoom() {		Room previousRoom = currentRoom.nextRoom("backward");		if (previousRoom == null) {			System.out.println("You cannot go back any further.");			return;		}		currentRoom = previousRoom;		System.out.println(currentRoom.longDescription());	}	private void printStatus() {		String status = "Player status:\n";		status += "HP: " + player.getHp() + "\n";		status += "Coins: " + player.getCoins() + "\n";		if (player.hasItem(ItemType.FLASHLIGHT)) {			int battery = player.getFlashlightBattery();			boolean flashlightOn = player.isFlashlightOn();			status += "Flashlight: " + battery + "%";			status += flashlightOn ? " (ON)\n" : " (OFF)\n";		} else {			status += "Flashlight: Not owned\n";		}		status += player.isAlive()				? "You are alive. Keep moving."				: "You are dead. Idk why you're still here.";		System.out.println(status);	}	/**	 * Bei einer Fehlsuche bleiben Coins und Items im Raum erhalten.	 */	private void searchRoom() {		if (failsInDarkness(SEARCH_FAIL_CHANCE)) {			System.out.println(					"It is too dark. You found nothing, try searching again."			);			return;		}		boolean foundSomething = false;		int coinsFound = currentRoom.collectCoins();		if (coinsFound > 0) {			player.addCoins(coinsFound);			System.out.println("You found " + coinsFound + " coins.");			foundSomething = true;		}		List<Item> itemsFound = currentRoom.collectItems();		for (Item item : itemsFound) {			player.addItem(item);			System.out.println("You found: " + item.getName());			foundSomething = true;		}		if (!foundSomething) {			System.out.println("You searched the room but found nothing.");		}	}	private boolean processCommand(Command command) {		if (command.isUnknown()) {			System.out.println("I don't know what you mean...");			return false;		}		String commandWord = command.getCommandWord();		if (commandWord.equals("help")) {			printHelp();		} else if (commandWord.equals("continue")) {			return continueToNextRoom();		} else if (commandWord.equals("return")) {			returnToPreviousRoom();		} else if (commandWord.equals("status")) {			printStatus();		} else if (commandWord.equals("search")) {			searchRoom();		} else if (commandWord.equals("inventory")) {			System.out.println(player.inventoryDescription());		} else if (commandWord.equals("flashlight")) {			useFlashlight(command);		} else if (commandWord.equals("quit")) {			if (command.hasSecondWord()) {				System.out.println("Quit what?");			} else {				return true;			}		}		return false;	}	private void useFlashlight(Command command) {		String action = command.getSecondWord();		if ("on".equals(action)) {			if (player.turnFlashlightOn()) {				System.out.println("You switched your flashlight on.");			} else {				System.out.println(						"You don't have a flashlight or its battery is empty."				);			}		} else if ("off".equals(action)) {			player.turnFlashlightOff();			System.out.println("You switched your flashlight off.");		} else {			System.out.println("Use: flashlight on / flashlight off");		}	}	private void printHelp() {		System.out.println("You've just entered the hotel.");		System.out.println("Everything should be normal, right?");		System.out.println();		System.out.println("Your command words are:");		System.out.println(parser.showCommands());		System.out.println("Flashlight: flashlight on / flashlight off");	}}